```js
let triggerEl = null;
const focusable = document.querySelectorAll('#delete-modal button');

function openModal(trigger) {
  triggerEl = trigger;
  document.getElementById('delete-modal').hidden = false;
  focusable[0].focus();
}

function closeModal() {
